const fs = require('fs');
const path = require('path');
const { JSDOM, VirtualConsole } = require('jsdom');

function out(obj) {
  process.stdout.write(JSON.stringify(obj) + '\n');
}

let inputs;
try {
  inputs = JSON.parse(fs.readFileSync(path.join(process.cwd(), 'inputs.json'), 'utf8'));
} catch (e) {
  out({ results: [], harness_error: 'failed to read inputs.json: ' + String((e && e.message) || e) });
  process.exit(0);
}

let src;
try {
  src = fs.readFileSync(path.join(process.cwd(), 'block-0.txt'), 'utf8');
} catch (e) {
  out({ results: [], harness_error: 'failed to read block-0.txt: ' + String((e && e.message) || e) });
  process.exit(0);
}

const START = 'function checkRequiredInputs() {';
const END = 'scrolling to the first error message\n  }\n}';
const si = src.indexOf(START);
const ei = si < 0 ? -1 : src.indexOf(END, si);
if (si < 0 || ei < 0) {
  out({ results: [], harness_error: 'candidate function anchors not found in block-0.txt' });
  process.exit(0);
}
const candidate = src.slice(si, ei + END.length);

function runCase(input) {
  const vc = new VirtualConsole();
  const errs = [];
  vc.on('jsdomError', (e) => { errs.push(String((e && e.message) || e)); });
  const html = String(input.html || '');
  const buttonId = String(input.button_id || 'submit');
  const dom = new JSDOM('<!DOCTYPE html><html><body>' + html + '</body></html>', {
    runScripts: 'outside-only',
    virtualConsole: vc
  });
  const w = dom.window;
  w.addEventListener('error', (e) => {
    errs.push(String((e.error && e.error.message) || e.message || e));
  });
  try {
    const attach = '\ndocument.getElementById(' + JSON.stringify(buttonId) +
      ').addEventListener("click", checkRequiredInputs);';
    w.eval(candidate + attach);
    const btn = w.document.getElementById(buttonId);
    if (!btn) {
      return { error: 'button with id ' + buttonId + ' not found in html' };
    }
    btn.dispatchEvent(new w.MouseEvent('click', { bubbles: true, cancelable: true }));
    if (errs.length > 0) {
      return { error: errs[0] };
    }
    const flagged_ids = [];
    const unflagged_ids = [];
    w.document.querySelectorAll('input[id]').forEach((inp) => {
      const nx = inp.nextElementSibling;
      const has = !!nx && nx.tagName === 'SPAN' && nx.textContent.trim().length > 0;
      if (has) { flagged_ids.push(inp.id); } else { unflagged_ids.push(inp.id); }
    });
    return { actual: { flagged_ids: flagged_ids, unflagged_ids: unflagged_ids } };
  } catch (e) {
    return { error: String((e && e.message) || e) };
  } finally {
    try { w.close(); } catch (_) { /* ignore */ }
  }
}

const results = [];
for (const item of inputs) {
  let r;
  try {
    r = runCase(item.input || {});
  } catch (e) {
    r = { error: String((e && e.message) || e) };
  }
  if (Object.prototype.hasOwnProperty.call(r, 'error')) {
    results.push({ id: item.id, error: r.error });
  } else {
    results.push({ id: item.id, actual: r.actual });
  }
}

out({ results: results });

extraction.end:
scrolling to the first error message
  }
