const fs = require('fs');
const path = require('path');
const vm = require('vm');

const realStdoutWrite = process.stdout.write.bind(process.stdout);
console.log = function () {};
console.info = function () {};
console.warn = function () {};
console.error = function () {};

function emit(obj) {
  realStdoutWrite(JSON.stringify(obj) + '\n');
}

function wait(ms) {
  return new Promise(function (resolve) { setTimeout(resolve, ms); });
}

function observe(document) {
  const els = Array.from(document.querySelectorAll('input'));
  const textInputs = els.filter(function (el) {
    const t = (el.getAttribute('type') || 'text').toLowerCase();
    return !!el.getAttribute('id') && t === 'text';
  });
  const flagged_ids = [];
  const unflagged_ids = [];
  textInputs.forEach(function (el) {
    let nx = el.nextSibling;
    while (nx && nx.nodeType !== 1) nx = nx.nextSibling;
    const hit = !!(nx && nx.tagName && String(nx.tagName).toUpperCase() === 'SPAN' &&
      String(nx.textContent || '').trim() !== '');
    if (hit) flagged_ids.push(el.getAttribute('id'));
    else unflagged_ids.push(el.getAttribute('id'));
  });
  return { flagged_ids: flagged_ids, unflagged_ids: unflagged_ids };
}

async function runCase(input, deps) {
  const parsed = deps.parseHTML('<!doctype html><html><head></head><body>' + String(input.html) + '</body></html>');
  const document = parsed.document;
  const window = parsed.window || document.defaultView;
  window.setTimeout = setTimeout;
  window.clearTimeout = clearTimeout;

  const $ = deps.jqFactory(window);
  const sandbox = {
    window: window,
    document: document,
    $: $,
    jQuery: $,
    setTimeout: setTimeout,
    clearTimeout: clearTimeout,
    alert: function () {},
    console: { log: function () {}, info: function () {}, warn: function () {}, error: function () {} }
  };
  vm.createContext(sandbox);
  vm.runInContext(deps.src, sandbox, { timeout: 4000 });

  await wait(20);

  const btn = document.getElementById(String(input.button_id));
  if (!btn) throw new Error('button not found: ' + String(input.button_id));
  btn.dispatchEvent(new window.Event('click', { bubbles: true }));

  await wait(20);
  return observe(document);
}

async function main() {
  let deps;
  let cases;
  try {
    const cwd = process.cwd();
    cases = JSON.parse(fs.readFileSync(path.join(cwd, 'inputs.json'), 'utf8'));
    deps = {
      src: fs.readFileSync(path.join(cwd, 'block-1.txt'), 'utf8'),
      parseHTML: require('linkedom').parseHTML,
      jqFactory: require('jquery')
    };
  } catch (e) {
    emit({ results: [], harness_error: 'setup failed: ' + (e && e.message ? e.message : String(e)) });
    return;
  }
  if (!Array.isArray(cases)) {
    emit({ results: [], harness_error: 'inputs.json is not an array' });
    return;
  }

  const results = [];
  for (const c of cases) {
    try {
      const actual = await runCase(c.input, deps);
      results.push({ id: c.id, actual: actual });
    } catch (e) {
      results.push({ id: c.id, error: e && e.message ? String(e.message) : String(e) });
    }
  }
  emit({ results: results });
}

main().catch(function (e) {
  emit({ results: [], harness_error: String((e && e.message) || e) });
});
